-- Edmonton practitioner directory, compiled by Arhm from public web sources.
--
-- Two things are carried through deliberately. `basis` records what each row is actually
-- evidenced by, because the source spreadsheet is explicit that 'Employer affiliation'
-- means someone works at an Islamically-integrated service and does NOT confirm their
-- personal religion. And no description asserts anyone's faith: rows carry profession,
-- specialty, and practice, which is what someone needing help after an incident actually
-- needs. Publishing an inferred religious identity for a named private individual is the
-- exact harm this project exists to avoid.
--
-- Source spreadsheet states: "No row was inferred from a person's name."

alter table support_resources drop constraint if exists support_resources_kind_check;
alter table support_resources add constraint support_resources_kind_check
  check (kind in ('police_non_emergency', 'human_rights', 'victim_services', 'legal_clinic',
                  'community_org', 'crisis_line', 'reporting_body', 'lawyer', 'counselling'));

alter table support_resources add column if not exists basis text;

on conflict do nothing;
